package pl.kyvaith.velvet.playback

import okhttp3.HttpUrl.Companion.toHttpUrl
import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test
import java.math.BigDecimal

/** Expectations are generated by executing pinned Kodi Python; this does not duplicate its builder. */
class KodiManifestRequestTest {
    private val reference: JSONObject = requireNotNull(javaClass.getResourceAsStream("/kodi/android_l1_manifest.json"))
        .bufferedReader().use { JSONObject(it.readText()) }

    @Test fun `complete Android manifest agrees with the independent Kodi oracle`() {
        val context = context()
        val profilesJson = reference.getJSONArray("profiles")
        val profiles = (0 until profilesJson.length()).map(profilesJson::getString)
        val cases = reference.getJSONArray("cases")
        for (index in 0 until cases.length()) {
            val case = cases.getJSONObject(index)
            val input = case.getJSONObject("input")
            val actual = KodiManifestRequest.create(input.getString("videoId"), input.getString("xid"),
                context, profiles, input.getString("hdcp"), input.getLong("clientTimeSeconds"))
            val expected = case.getJSONObject("request").getJSONObject("params")
            assertTrue("Kodi manifest differs for ${case.getString("name")}\nExpected: ${expected.toString(2)}\nActual: ${actual.toString(2)}",
                deepJsonEquals(expected, actual))
        }
    }

    @Test fun `manifest endpoint agrees with Kodi including browser name case and website build version`() {
        session(context()).use { session ->
            val expected = reference.getJSONArray("cases").getJSONObject(0).getString("endpoint").toHttpUrl()
            val actual = session.endpoint(NetflixMslSession.MANIFEST_ENDPOINT, "prefetch/licensedManifest").toHttpUrl()
            assertEquals(expected, actual)
        }
    }

    @Test fun `empty website metadata retains the complete Kodi query shape`() {
        val empty = context().copy(uiVersion = "", clientVersion = "", browserVersion = "",
            osName = "", osVersion = "", buildIdentifier = "")
        session(empty).use { session ->
            assertEquals(reference.getString("emptyMetadataEndpoint").toHttpUrl(),
                session.endpoint(NetflixMslSession.MANIFEST_ENDPOINT, "prefetch/licensedManifest").toHttpUrl())
        }
    }

    @Test fun `declared Android playback identity and user agent agree with the Kodi oracle`() {
        val device = reference.getJSONObject("device")
        assertEquals(reference.getString("nativeIdentity"), AndroidPlaybackIdentity.create(
            device.getString("manufacturer"), device.getString("model"), device.getString("systemId"),
            device.getString("securityLevel"), device.getString("suffix")))
        assertEquals(reference.getString("userAgent"), KodiAndroidPlaybackProfile.USER_AGENT)
    }

    /** Android's compile-time JSONObject API does not expose the JVM library's similar(). */
    private fun deepJsonEquals(expected: Any?, actual: Any?): Boolean {
        if (expected == null || expected === JSONObject.NULL) return actual == null || actual === JSONObject.NULL
        if (actual == null || actual === JSONObject.NULL) return false
        return when {
            expected is JSONObject && actual is JSONObject -> {
                val expectedKeys = expected.keys().asSequence().toSet()
                val actualKeys = actual.keys().asSequence().toSet()
                expectedKeys == actualKeys && expectedKeys.all { deepJsonEquals(expected.get(it), actual.get(it)) }
            }
            expected is JSONArray && actual is JSONArray -> expected.length() == actual.length() &&
                (0 until expected.length()).all { deepJsonEquals(expected.get(it), actual.get(it)) }
            expected is Number && actual is Number -> runCatching {
                BigDecimal(expected.toString()).compareTo(BigDecimal(actual.toString())) == 0
            }.getOrDefault(false)
            expected is String && actual is String -> expected == actual
            expected is Boolean && actual is Boolean -> expected == actual
            else -> false
        }
    }

    private fun context(): PlaybackContext {
        val data = reference.getJSONObject("context")
        return PlaybackContext("NetflixId=synthetic-a; SecureNetflixId=synthetic-b", "synthetic-auth",
            reference.getString("nativeIdentity"), "synthetic-profile", reference.getString("userAgent"),
            clientVersion = data.getString("clientVersion"), uiVersion = data.getString("uiVersion"),
            browserVersion = data.getString("browserVersion"), osName = data.getString("osName"),
            osVersion = data.getString("osVersion"), buildIdentifier = data.getString("buildIdentifier"),
            locale = data.getString("locale"))
    }

    private fun session(context: PlaybackContext): NetflixMslSession = NetflixMslSession(
        BoundPlaybackSession(context, NetflixSessionProvider { context }),
        MslTransport { _, _, _, _, _ -> throw AssertionError("Endpoint construction must not perform network I/O") },
        UnusedCrypto,
        authenticationMode = MslAuthenticationMode.COOKIE_SESSION,
    )

    private object UnusedCrypto : MslCrypto {
        override val keyExchangeScheme = "WIDEVINE"
        override fun keyRequest(): JSONObject = error("No handshake in endpoint test")
        override fun acceptKeyResponse(keyResponse: JSONObject) = error("No handshake in endpoint test")
        override fun encrypt(plaintext: ByteArray): ByteArray = error("No message in endpoint test")
        override fun decrypt(envelope: ByteArray): ByteArray = error("No message in endpoint test")
        override fun sign(message: ByteArray): ByteArray = error("No message in endpoint test")
        override fun verify(message: ByteArray, signature: ByteArray): Boolean = error("No message in endpoint test")
        override fun close() = Unit
    }
}
